        // Numbers start again at D-001 every night, so the number and phone alone can be another night's booking: the
        // night of the confirmation being edited says which (p_session_id is the night it moves to).
        if (editing.session && editing.session.id) edit.p_from_session = editing.session.id;
        r = await call("rider_edit", edit, ["p_lang", "p_from_session"]);
